messages.content:
Tool response:
Tool: create_event_type
Description: Create Event Type
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "title": "Name",
          "description": "Name of the event type"
        },
        "duration_minutes": {
          "type": "integer",
          "exclusiveMinimum": 0.0,
          "title": "Duration Minutes",
          "description": "Duration of the event in minutes"
        },
        "location": {
          "type": "string",
          "title": "Location",
          "description": "Location of the event"
        },
        "calendar_sync_required": {
          "type": "boolean",
          "title": "Calendar Sync Required",
          "description": "Whether calendar sync is required"
        },
        "availability_rules": {
          "items": {
            "properties": {
              "day_of_week": {
                "type": "integer",
                "maximum": 6.0,
                "minimum": 0.0,
                "title": "Day Of Week",
                "description": "Day of week (0=Sunday, 1=Monday, ..., 6=Saturday)"
              },
              "start_time": {
                "type": "string",
                "pattern": "^[0-2][0-9]:[0-5][0-9]$",
                "title": "Start Time",
                "description": "Start time in HH:MM format"
              },
              "end_time": {
                "type": "string",
                "pattern": "^[0-2][0-9]:[0-5][0-9]$",
                "title": "End Time",
                "description": "End time in HH:MM format"
              }
            },
            "type": "object",
            "required": [
              "day_of_week",
              "start_time",
              "end_time"
            ],
            "title": "AvailabilityRule"
          },
          "type": "array",
          "minItems": 1,
          "title": "Availability Rules",
          "description": "Array of availability rules for the event type"
        },
        "questions": {
          "items": {
            "properties": {
              "question_text": {
                "type": "string",
                "title": "Question Text",
                "description": "Text of the question"
              },
              "question_type": {
                "type": "string",
                "title": "Question Type",
                "description": "Type of the question"
              },
              "is_required": {
                "type": "boolean",
                "title": "Is Required",
                "description": "Whether the question is required"
              }
            },
            "type": "object",
            "required": [
              "question_text",
              "question_type",
              "is_required"
            ],
            "title": "Question"
          },
          "type": "array",
          "minItems": 1,
          "title": "Questions",
          "description": "Array of questions for the event type"
        }
      },
      "required": [
        "name",
        "duration_minutes",
        "location",
        "calendar_sync_required",
        "availability_rules",
        "questions"
      ]
    }
